#' Open the jabotR field notebook
#'
#' @author
#' Giulia Cavalcanti Ottino
#' Domingos Cardoso
#'
#' @description
#' Opens the interactive jabotR field notebook in the user's default web
#' browser. The application is distributed with the package and works
#' locally without an internet connection.
#'
#' The field notebook allows users to organize collection-event and
#' specimen data, export a standardized JABOT spreadsheet, and generate
#' a printable field notebook in PDF format.
#'
#' With `merge = TRUE`, a field notebook PDF previously generated by
#' `jabot_fieldbook()` is detected and its collection events are loaded
#' back into the notebook. A new collection event is opened with the next
#' number of the collector's sequence, so that the next PDF generated is a
#' new, more complete version of the field notebook covering the whole
#' collection-number sequence.
#'
#' @param browser Logical. If `TRUE`, opens the field notebook in the
#'   default web browser. If `FALSE`, only returns the local path to the
#'   application.
#'
#' @param merge Logical. If `TRUE`, searches for a field notebook PDF
#'   previously generated by `jabot_fieldbook()` and merges its content
#'   into the notebook. Defaults to `FALSE`.
#'
#' @param pdf_path Optional. Used only when `merge = TRUE`. Either the path
#'   to a specific field notebook PDF or a directory in which to search for
#'   one (files named `fieldbook_*.pdf`). When several notebooks are found,
#'   the most recently modified one is used. If `NULL` (default), the
#'   current working directory and the user's `Downloads` folder are
#'   searched.
#'
#' @return
#' Invisibly returns the local path to the field notebook `index.html`.
#' When a previous notebook is merged, this is a temporary copy of the
#' application that carries the merged data.
#'
#' @details
#' The field notebook runs locally using HTML, CSS, and JavaScript files
#' distributed with jabotR. It does not require Shiny or an internet
#' connection. Spreadsheet generation is performed locally in the browser.
#'
#' Every field notebook PDF embeds a machine-readable copy of its data as
#' nearly transparent text behind the notebook content (invisible on screen
#' and on paper, and it never adds pages). This is what allows
#' `merge = TRUE` to rebuild the notebook from the PDF. Merging requires the suggested packages \pkg{pdftools} and
#' \pkg{jsonlite}. PDFs generated before this feature was introduced, or
#' printed with a method that discards text (e.g. "print as image"),
#' cannot be merged.
#'
#' The previous collection events are loaded collapsed, marked as coming
#' from the previous notebook, and remain editable. They are included in
#' the new PDF, but the JABOT spreadsheet exported from the merged notebook
#' contains only the new collection events (and is named after their
#' collection-number range), so records already submitted to JABOT are not
#' duplicated.
#'
#' @examples
#' \dontrun{
#' jabot_fieldbook()
#'
#' # Continue the most recent field notebook found in the working
#' # directory or in the Downloads folder
#' jabot_fieldbook(merge = TRUE)
#'
#' # Continue a specific field notebook
#' jabot_fieldbook(
#'   merge = TRUE,
#'   pdf_path = "fieldbook_Cardoso2020-2052.pdf"
#' )
#' }
#'
#' @export

jabot_fieldbook <- function(browser = TRUE,
                            merge = FALSE,
                            pdf_path = NULL) {

  if (!is.logical(browser) ||
      length(browser) != 1L ||
      is.na(browser)) {

    stop(
      "`browser` must be TRUE or FALSE.",
      call. = FALSE
    )
  }

  if (!is.logical(merge) ||
      length(merge) != 1L ||
      is.na(merge)) {

    stop(
      "`merge` must be TRUE or FALSE.",
      call. = FALSE
    )
  }

  if (!is.null(pdf_path) &&
      (!is.character(pdf_path) ||
       length(pdf_path) < 1L ||
       anyNA(pdf_path) ||
       !all(nzchar(pdf_path)))) {

    stop(
      "`pdf_path` must be NULL or the path to a PDF file or directory.",
      call. = FALSE
    )
  }

  app <- system.file(
    "jabot_fieldbook",
    "index.html",
    package = "jabotR"
  )

  if (!nzchar(app) || !file.exists(app)) {

    stop(
      paste0(
        "The jabotR field notebook could not be found.\n",
        "Reinstall jabotR and try again."
      ),
      call. = FALSE
    )
  }

  app <- normalizePath(
    app,
    winslash = "/",
    mustWork = TRUE
  )

  if (isTRUE(merge)) {

    previous <- .fieldbook_find_previous(pdf_path)

    if (!is.null(previous)) {
      app <- .fieldbook_merged_app(app, previous)
    }
  }

  if (isTRUE(browser)) {

    encoded_path <- utils::URLencode(
      app,
      reserved = FALSE
    )

    url <- if (.Platform$OS.type == "windows") {
      paste0("file:///", encoded_path)
    } else {
      paste0("file://", encoded_path)
    }

    utils::browseURL(url)
  }

  invisible(app)
}


# Markers written by inst/jabot_fieldbook/app.js (fieldbookDataText()).
.fieldbook_data_begin <- "JABOTR-FIELDBOOK-DATA-BEGIN"
.fieldbook_data_end <- "JABOTR-FIELDBOOK-DATA-END"
.fieldbook_data_format <- "jabotR-fieldbook"


.fieldbook_require_merge_pkgs <- function() {

  missing <- c("pdftools", "jsonlite")[
    !vapply(
      c("pdftools", "jsonlite"),
      requireNamespace,
      logical(1),
      quietly = TRUE
    )
  ]

  if (length(missing)) {
    stop(
      paste0(
        "`merge = TRUE` requires the package(s): ",
        paste(missing, collapse = ", "),
        ".\nInstall with install.packages(c(",
        paste0('"', missing, '"', collapse = ", "),
        "))."
      ),
      call. = FALSE
    )
  }

  invisible(TRUE)
}


.fieldbook_downloads_dir <- function() {

  home <- if (.Platform$OS.type == "windows") {
    Sys.getenv("USERPROFILE", unset = path.expand("~"))
  } else {
    path.expand("~")
  }

  file.path(home, "Downloads")
}


# Candidate PDF files: an explicit file, or fieldbook_*.pdf in directories.
.fieldbook_candidate_pdfs <- function(pdf_path = NULL) {

  locations <- if (is.null(pdf_path)) {
    unique(c(getwd(), .fieldbook_downloads_dir()))
  } else {
    pdf_path
  }

  files <- character(0)

  for (location in locations) {

    if (dir.exists(location)) {

      files <- c(
        files,
        list.files(
          location,
          pattern = "^fieldbook_.*\\.pdf$",
          ignore.case = TRUE,
          full.names = TRUE
        )
      )

    } else if (file.exists(location)) {

      files <- c(files, location)

    } else if (!is.null(pdf_path)) {

      stop(
        paste0("`pdf_path` not found: ", location),
        call. = FALSE
      )
    }
  }

  unique(normalizePath(files, winslash = "/", mustWork = FALSE))
}


# Extract the embedded field book data from a PDF.
# Returns list(file, data, payload) or NULL when the PDF carries no data.
.fieldbook_read_pdf <- function(file) {

  pattern <- paste0(
    .fieldbook_data_begin,
    ":([0-9]+):([A-Za-z0-9+/=]+):",
    .fieldbook_data_end
  )

  find_block <- function(text) {
    # Extraction breaks the block into lines and pages; neither the
    # markers nor base64 contain whitespace.
    text <- gsub("\\s+", "", paste(text, collapse = ""))
    # Some PDF producers turn "-" into typographic dashes or minus signs;
    # base64 never contains dashes, so normalizing them is safe.
    text <- gsub("[\u2010-\u2015\u2212]", "-", text)
    regmatches(text, regexec(pattern, text, perl = TRUE))[[1]]
  }

  # 1) The app prints the block in a monospaced font behind the notebook
  #    text, so its lines interleave with the content: keep only the
  #    words set in a monospaced font, in reading order.
  hit <- tryCatch(
    {
      words <- pdftools::pdf_data(file, font_info = TRUE)
      words <- do.call(
        rbind,
        lapply(seq_along(words), function(i) {
          w <- words[[i]]
          if (!nrow(w)) return(NULL)
          w$page <- i
          w[, c("page", "x", "y", "font_name", "text")]
        })
      )
      mono <- words[grepl("courier|mono", words$font_name, ignore.case = TRUE), ]
      mono <- mono[order(mono$page, mono$y, mono$x), ]
      find_block(mono$text)
    },
    error = function(e) character(0)
  )

  # 2) Fallback: plain text extraction of the whole document.
  if (length(hit) != 3L) {
    hit <- tryCatch(
      find_block(pdftools::pdf_text(file)),
      error = function(e) character(0)
    )
  }

  if (length(hit) != 3L) {
    return(NULL)
  }

  data <- hit[3]

  if (nchar(data) != as.integer(hit[2])) {
    warning(
      paste0(
        "The field notebook data embedded in ", basename(file),
        " is incomplete and was ignored."
      ),
      call. = FALSE
    )
    return(NULL)
  }

  payload <- tryCatch(
    {
      json <- rawToChar(jsonlite::base64_dec(data))
      Encoding(json) <- "UTF-8"
      jsonlite::fromJSON(json, simplifyVector = FALSE)
    },
    error = function(e) NULL
  )

  if (!is.list(payload) ||
      !identical(payload$format, .fieldbook_data_format) ||
      !is.list(payload$events) ||
      !length(payload$events)) {
    return(NULL)
  }

  list(file = file, data = data, payload = payload)
}


.fieldbook_summary <- function(payload) {

  specimens <- unlist(
    lapply(payload$events, function(event) event$specimens),
    recursive = FALSE
  )

  numbers <- vapply(
    specimens,
    function(specimen) {
      value <- specimen$number
      if (is.null(value)) NA_character_ else as.character(value)
    },
    character(1)
  )

  numbers <- numbers[!is.na(numbers) & grepl("^[0-9]+$", numbers)]

  list(
    events = length(payload$events),
    specimens = length(specimens),
    last = if (length(numbers)) max(as.numeric(numbers)) else NA_real_
  )
}


# Find the most recent field book PDF generated by jabot_fieldbook().
.fieldbook_find_previous <- function(pdf_path = NULL) {

  .fieldbook_require_merge_pkgs()

  files <- .fieldbook_candidate_pdfs(pdf_path)

  found <- Filter(Negate(is.null), lapply(files, .fieldbook_read_pdf))

  if (!length(found)) {

    where <- if (is.null(pdf_path)) {
      paste(unique(c(getwd(), .fieldbook_downloads_dir())), collapse = ", ")
    } else {
      paste(pdf_path, collapse = ", ")
    }

    msg <- paste0(
      "No field notebook PDF generated by jabot_fieldbook() was found in: ",
      where,
      ". Opening an empty field notebook."
    )

    if (length(pdf_path) == 1L && !dir.exists(pdf_path)) {
      stop(
        paste0(
          "`pdf_path` is not a field notebook PDF generated by ",
          "jabot_fieldbook() (no embedded data was found): ",
          pdf_path
        ),
        call. = FALSE
      )
    }

    warning(msg, call. = FALSE)
    return(NULL)
  }

  mtimes <- vapply(
    found,
    function(item) as.numeric(file.mtime(item$file)),
    numeric(1)
  )

  previous <- found[[which.max(mtimes)]]
  info <- .fieldbook_summary(previous$payload)

  message(
    "Merging previous field notebook: ", previous$file, "\n",
    "  ", info$events, " collection event(s), ",
    info$specimens, " specimen(s)",
    if (!is.na(info$last)) {
      paste0(
        "; collection numbers continue from ",
        format(info$last + 1, scientific = FALSE)
      )
    },
    "."
  )

  previous
}


# Copy the application to a temporary folder and inject the merge data.
.fieldbook_merged_app <- function(app, previous) {

  src <- dirname(app)

  dest <- tempfile("jabot_fieldbook_")
  dir.create(dest, recursive = TRUE, showWarnings = FALSE)

  ok <- file.copy(
    list.files(src, full.names = TRUE, all.files = FALSE),
    dest,
    recursive = TRUE
  )

  if (!all(ok)) {
    stop(
      "Could not prepare a copy of the field notebook for merging.",
      call. = FALSE
    )
  }

  merge_js <- paste0(
    "window.JABOTR_FIELDBOOK_MERGE = ",
    jsonlite::toJSON(
      list(
        source = basename(previous$file),
        data = previous$data
      ),
      auto_unbox = TRUE
    ),
    ";\n"
  )

  writeLines(
    merge_js,
    file.path(dest, "jabot-merge-data.js"),
    useBytes = TRUE
  )

  index_file <- file.path(dest, "index.html")
  index <- readLines(index_file, warn = FALSE, encoding = "UTF-8")

  app_line <- grep('src="app\\.js"', index)[1]

  if (is.na(app_line)) {
    stop(
      "Could not prepare the field notebook for merging.",
      call. = FALSE
    )
  }

  index <- append(
    index,
    '  <script src="jabot-merge-data.js" defer></script>',
    after = app_line - 1L
  )

  con <- file(index_file, open = "w", encoding = "UTF-8")
  on.exit(close(con), add = TRUE)
  writeLines(index, con)

  normalizePath(index_file, winslash = "/", mustWork = TRUE)
}
